def play(secret):
    attempts = 0
    while True:
        try:
            text = input("Guess or quit: ").strip().lower()
        except EOFError:
            return None
        if text == "quit":
            return None
        try:
            guess = int(text)
        except ValueError:
            print("Number needed")
            continue
        attempts += 1
        if guess < secret:
            print("Higher")
        elif guess > secret:
            print("Lower")
        else:
            print("Correct")
            return attempts
